package com.example.lokihealbe;
import android.content.*;import com.healbe.healbesdk.business_api.*;import com.healbe.healbesdk.business_api.user.data.HealbeSessionState;import com.healbe.healbesdk.business_api.healthdata.data.energy.EnergySummary;import java.time.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;import org.json.*;
final class CloudSync {
 static final AtomicBoolean busy=new AtomicBoolean();
 private static int generation;
 private static final Object initLock=new Object();private static boolean initialized;
 static synchronized void stop(Context c){generation++;c.stopService(new Intent(c,SyncService.class));c.getSharedPreferences("link",0).edit().putBoolean("linked",false).commit();SnapshotStore.clear(c);state(c,"連携を停止しました");}
 static void state(Context c,String value){c.getSharedPreferences("link",0).edit().putString("status",value).apply();}
 static void init(Context c)throws Exception{synchronized(initLock){if(initialized)return;HealbeSdk.init(c.getApplicationContext(),new HealbeSdk.Configuration.Builder().setAppVersion("Loki-HEALBE-0.1").build()).timeout(15,TimeUnit.SECONDS).blockingAwait();initialized=true;}}
 static boolean login(Context c,String email,String password)throws Exception{int ticket; synchronized(CloudSync.class){ticket=generation;}init(c);HealbeSdk sdk=HealbeSdk.get();sdk.USER.prepareSession().timeout(15,TimeUnit.SECONDS).blockingGet();HealbeSessionState state=sdk.USER.login(email,password).timeout(20,TimeUnit.SECONDS).blockingGet();synchronized(CloudSync.class){if(ticket!=generation)return false;boolean valid=HealbeSessionState.isUserValid(state);c.getSharedPreferences("link",0).edit().putBoolean("linked",valid).commit();return valid;}}
 static void refresh(Context c){if(!busy.compareAndSet(false,true))return;String stage="init";try{if(!c.getSharedPreferences("link",0).getBoolean("linked",false)){state(c,"ログインが必要です");return;}init(c);stage="session";HealbeSdk sdk=HealbeSdk.get();if(!HealbeSessionState.isUserValid(sdk.USER.prepareSession().timeout(15,TimeUnit.SECONDS).blockingGet())){state(c,"再ログインが必要です");return;}
   stage="deviceConnection";if(!sdk.GOBE.isReady().timeout(5,TimeUnit.SECONDS).blockingGet()){sdk.GOBE.connect().andThen(sdk.GOBE.observeConnectionState()).filter(v->v==com.healbe.healbesdk.device_api.ClientState.READY).firstOrError().timeout(40,TimeUnit.SECONDS).blockingGet();}stage="tasks";state(c,"HEALBEのサーバー同期を確認中");java.util.concurrent.CountDownLatch syncDone=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.atomic.AtomicBoolean syncStarted=new java.util.concurrent.atomic.AtomicBoolean();io.reactivex.disposables.Disposable watch=sdk.TASKS.observeSyncState().subscribe(v->{if(v==com.healbe.healbesdk.business_api.tasks.entity.SyncState.START)syncStarted.set(true);if(syncStarted.get()&&v==com.healbe.healbesdk.business_api.tasks.entity.SyncState.END)syncDone.countDown();},e->{});try{sdk.TASKS.startTasks().timeout(10,TimeUnit.SECONDS).blockingAwait();stage="syncCompletion";if(!syncDone.await(90,TimeUnit.SECONDS))throw new TimeoutException("sync not completed");}finally{watch.dispose();}
   stage="summary";EnergySummary summary=sdk.HEALTH_DATA.getEnergySummary(0).filter(v->v.get()!=null).map(v->v.get()).firstOrError().timeout(30,TimeUnit.SECONDS).blockingGet();
   stage="validate";long now=System.currentTimeMillis(),measured=sdk.HEALTH_DATA.getEnergyDataMaxTimestamp().firstOrError().timeout(5,TimeUnit.SECONDS).blockingGet();if(measured>0&&measured<100000000000L)measured*=1000;
   float in=summary.getEnergyIn(),out=summary.getEnergyOut();if(!Float.isFinite(in)||!Float.isFinite(out)||in<0||out<0)throw new IllegalStateException("invalid energy");int balance=Math.round(in-out);if(Math.abs(balance)>15000||measured<=0||measured>now+30000)throw new IllegalStateException("invalid energy time");
   String day=Instant.ofEpochMilli(measured).atZone(ZoneId.systemDefault()).toLocalDate().toString();synchronized(CloudSync.class){if(!c.getSharedPreferences("link",0).getBoolean("linked",false))return;stage="cache";SnapshotStore.write(c,new JSONObject().put("balanceKcal",balance).put("measuredAt",measured).put("observedAt",now).put("date",day).put("source","HEALBE_SDK").put("provisional",true));c.getSharedPreferences("link",0).edit().remove("failureStage").remove("failureType").putLong("lastSuccessAt",now).apply();state(c,day.equals(LocalDate.now().toString())?"収支を受信しました":"前日以前のデータです。新しい同期を待っています");}
  }catch(Exception error){Throwable cause=error;for(int i=0;i<8&&cause.getCause()!=null;i++)cause=cause.getCause();c.getSharedPreferences("link",0).edit().putString("failureStage",stage).putString("failureType",cause.getClass().getSimpleName()).apply();state(c,"収支を受信できませんでした（"+stage+"）。ログイン・HEALBE側の同期状況を確認してください");}
  finally{try{HealbeSdk.get().TASKS.stopTasks().timeout(5,TimeUnit.SECONDS).blockingAwait();}catch(Exception ignored){}busy.set(false);}
 }
}
